#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
uniform float2 amzVelocity,amzPivot,amzScale;
uniform float amzAngularVelocity,amzScaleVelocity,amzStartTime,amzEndTime;

struct AC_ImageInfo { int texture; float2 amzLocal_size; };
const float3x3 labPlaneInverse=float3x3(1);
float4x4 amzQuaternion(float4 q) {
    q /= max(length(q),0.000001);
    float x=q.x,y=q.y,z=q.z,w=q.w;
    return float4x4(1-2*(y*y+z*z),2*(x*y+w*z),2*(x*z-w*y),0,
                    2*(x*y-w*z),1-2*(x*x+z*z),2*(y*z+w*x),0,
                    2*(x*z+w*y),2*(y*z-w*x),1-2*(x*x+y*y),0,0,0,0,1);
}
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval(((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0))); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
float4 amzTexture(int tex,float2 uv,float bias){return amzTexture(tex,uv);}
uniform float amzp_ITERATIONS;
uniform float amzp_progressa;
uniform float amzp_RADIUS;
uniform float amzp_GAMMA;
uniform float amzp_IRIS_MODE;
uniform float amzp_IRIS_SIDES;
uniform float amzp_IRIS_CURVATURE;
uniform float amzp_IRIS_ROTATION;
uniform float amzp_SCALE_X;
uniform float amzp_SCALE_Y;
uniform float amzp_BOKEH_SHADING;
uniform float amzp_FOCUS_X;
uniform float amzp_FOCUS_Y;
uniform float amzp_FOCUS_RADIUS;
uniform float amzp_FOCUS_SOFTNESS;
uniform float amzp_bright;
uniform float amzp_alpha;
uniform float amzp_blendMode;
    float2x2 rot2m(float a) {
        float s = sin(a);
        float c = cos(a);
        return float2x2(c, -s, s, c);
    }
    float irisMask(float2 p, float sides, float curvature) {
        float r = length(p);
        if (r == 0.0) return 1.0;
        float angle = atan(p.y, p.x);
        float sector = 2.0 * 3.14159265359 / sides;
        float a = mod(angle, sector) - 0.5 * sector;
        float radiusEdge = cos(0.5 * sector) / cos(a);
        float t = clamp(curvature * 0.5 + 0.5, 0.0, 1.0);
        radiusEdge = mix(radiusEdge, 1.0, t);
        float m = smoothstep(radiusEdge, radiusEdge - 0.02, r);
        return m;
    }
    float focusFactor(float2 uv) {
        if (amzp_FOCUS_RADIUS <= 0.0) return 1.0;
        float2 focusPoint = float2(amzp_FOCUS_X, amzp_FOCUS_Y);
        float d = distance(uv, focusPoint);
        float inner = amzp_FOCUS_RADIUS;
        float outer = amzp_FOCUS_RADIUS + amzp_FOCUS_SOFTNESS;
        outer = max(outer, inner + 0.001);
        return smoothstep(inner, outer, d);
    }
    float3 LensBokeh(int tex, float2 uv, float radiusNorm) {
        if (radiusNorm <= 0.0) {
            return amzTexture(tex, uv).rgb;
        }
        float iter = max(1.0, float(amzp_ITERATIONS));
        float2 vangle = float2(0.0, radiusNorm / sqrt(iter));
        float2x2 rot=rot2m(2.3999632);
        float3 acc = float3(0.0);
        float3 div = float3(0.0);
        float r = 1.0;
        float sides = max(3.0, amzp_IRIS_SIDES);
        bool usePolygon = (int(amzp_IRIS_MODE) == 1);
        float irisRad = radians(amzp_IRIS_ROTATION);
        float2x2 irisRotM = rot2m(irisRad);
        for (float j = 0.0; j < amzp_ITERATIONS; j++) {
            r += 1.0 / r;
            vangle = rot * vangle;
            float2 offset = (r - 1.0) * vangle;
            float2 pNorm = offset / radiusNorm;
            pNorm *= float2(amzp_SCALE_X, amzp_SCALE_Y);
            pNorm = irisRotM * pNorm;
            float mask = 1.0;
            if (usePolygon) {
                mask = irisMask(pNorm, sides, amzp_IRIS_CURVATURE);
            }
            if (mask <= 0.0) continue;
            float dist = clamp(length(pNorm), 0.0, 1.0);
            float shade = mix(1.0, 1.0 - dist, amzp_BOKEH_SHADING);
            float3 col = amzTexture(tex, uv + offset).rgb;
            float3 w = pow(col, float3(amzp_GAMMA));
            acc += col * w * mask * shade;
            div += w * mask * shade;
        }
        float divSum = div.x + div.y + div.z;
        if (divSum <= 0.0) {
            return amzTexture(tex, uv).rgb;
        }
        return acc / div;
    }
    void amzRender() {
        float2 uv = amzScreenNorm();
        float4 texColor = amzTexture(0, uv);
        float baseRadiusNorm = amzp_RADIUS * amzp_progressa * 0.01;
        float fFactor = focusFactor(uv);
        float radiusNorm = baseRadiusNorm * fFactor;
        float3 blurRGB = LensBokeh(0, uv, radiusNorm);
        float4 blurColor = float4(blurRGB, texColor.a);
        float4 factor = mix(texColor, blurColor, amzp_alpha);
        float4 resultfinal;
        if (int(amzp_blendMode) == 0) {
            resultfinal = factor * amzp_bright;
            resultfinal.a = texColor.a;
        } else if (int(amzp_blendMode) == 1) {
            factor *= amzp_bright;
            float4 c = factor + float4(1.0) * (1.0 - factor.a);
            resultfinal = float4((texColor.rgb / max(texColor.a, 1e-3)) * c.rgb, 1.0) * texColor.a;
        } else if (int(amzp_blendMode) == 2) {
            factor *= amzp_bright;
            float3 src = texColor.rgb / max(texColor.a, 1e-3);
            float3 scr = 1.0 - ((1.0 - src) * (1.0 - factor.rgb));
            resultfinal = float4(scr, 1.0) * texColor.a;
        }
        amzOutput = resultfinal;
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }

